// Recovery/checkpoint finisher for a fully constructed quantity copy in the same host.
// Refuses missing baseline state, changed DLL, changed diagnostic source or an existing output.
using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro{public static class LatchInProcess{
static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=64000000};static IZSceneDoc S;static IZSceneDocUtility U;static Type Baseline,Controller;static List<object> Checks;static string Progress;static object Manifest;
static Dictionary<string,object> O(object x){return (Dictionary<string,object>)x;}static IZDoc D(object x){return x is IZDoc?(IZDoc)x:(IZDoc)Marshal.GetObjectForIUnknown(new IntPtr(Convert.ToInt64(x)));}
static string Hash(string p){using(var f=File.OpenRead(p))using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
static void Mark(string t){File.AppendAllText(Progress,DateTime.UtcNow.ToString("o")+" "+t+Environment.NewLine);}
static void ResetScene(IZDoc d){S=(IZSceneDoc)d;U=(IZSceneDocUtility)S;Baseline.GetField("S",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,S);Baseline.GetField("U",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,U);}
static void Update(){Mark("batch suppression start");Controller.GetMethod("Apply").Invoke(null,new object[]{S});Mark("materialize target plates/profiles");var members=((object[])O(Manifest)["rows"]).Select(O).SelectMany(r=>(object[])r["slots"]).SelectMany(a=>(object[])a).Select(id=>U.GetElementById(Convert.ToInt32(id))).Where(e=>e.Type!=eZElementType.Z_ELEMENT_ASSEMBLY&&e.Type!=eZElementType.Z_ELEMENT_PART).Select(e=>e.GetOwnerPart()).GroupBy(e=>e.Id).Select(g=>g.First());foreach(var e in members){var p=(IZPart)e;p.Update();p.GetBody(true).GetBoundingBox();}S.Update();Mark("materialized");}
static void Check(string name){Mark("check "+name);Update();var c=(Dictionary<string,object>)Baseline.GetMethod("Check",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{name});Checks.Add(c);if(!(bool)c["passed"])throw new Exception("Native geometry check failed "+name);}
static void Picture(string p){var c=(IZCamera)S.CameraMgr.ActiveCamera;c.Perspective=false;c.Direction=new double[]{.65,.85,-.5};c.Up=new double[]{0,0,1};S.AdjustCameraToFitShapeInRect(1500,1100);S.Redraw();S.ExportImage(p,eZImageFormat.Z_IMAGE_PNG,1500,1100,true);}
public static int Run(string folder){var result=new Dictionary<string,object>();IZDoc owned=null;bool pass=false;Checks=new List<object>();Progress=Path.Combine(folder,"progress.txt");try{
 var q=O(J.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json"))));if((string)q["contract"]!="rockpro-tv-counts-resume-v1"||System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(q["expected_pid"]))throw new Exception("Wrong host/request");
 dynamic legacy=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)legacy.ZIronCADApp;if(!app.ApiVersion.StartsWith("29."))throw new Exception("2027 required");var before=((Array)app.GetAllOpenDocs()).Cast<object>().Select(D).Select(d=>new{path=d.Name,modified=d.Modified}).ToArray();
 string source=(string)q["source"],output=(string)q["output"],assembly=(string)q["assembly"];if(Hash(source)!=(string)q["sha256"]||Hash(assembly)!=(string)q["assembly_sha256"]||File.Exists(output))throw new Exception("Source/assembly changed or output exists");
 Baseline=Assembly.LoadFrom(assembly).GetType("RockPro.LatchInProcess");var bindings=Baseline.GetField("Bindings",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null) as IList;if(bindings==null||bindings.Count!=112)throw new Exception("No matching host baseline. Rebuild from preserved source instead.");
 foreach(var a in AppDomain.CurrentDomain.GetAssemblies()){var t=a.GetType("RockPro.CAD.MountCountController");if(t!=null)t.GetMethod("Stop").Invoke(null,null);}
 Controller=Assembly.LoadFrom((string)q["controller"]).GetType("RockPro.CAD.MountCountController");Controller.GetField("Suspended").SetValue(null,true);Mark("controller "+Controller.Assembly.FullName+" at "+Controller.Assembly.Location);
 string work=Path.Combine(folder,"working.ics");File.Copy(source,work,false);bool already;owned=app.OpenFile2(work,false,true,out already);if(already){owned=null;throw new Exception("Already open");}ResetScene(owned);
 Manifest=J.DeserializeObject((string)S.GetTopElement().get_CustomPropMgr(false).GetValueByName("RockPro.MountCounts.v1"));if((string)O(Manifest)["contract"]!="rockpro-tv-counts-v1")throw new Exception("Wrong manifest");
 var rows=((object[])O(Manifest)["rows"]).Select(O).ToArray();var defaults=Enumerable.Range(0,S.ParameterMgr.Count).Select(i=>S.ParameterMgr.GetParameter(i)).ToDictionary(p=>p.Name,p=>p.Expression);Action restore=()=>{foreach(var p in defaults)S.ParameterMgr.GetParameterByName(p.Key).Expression=p.Value;};
 Check("po_dwa_po_materializacji");Picture(Path.Combine(folder,"po_dwa.png"));
 foreach(var r in rows)S.ParameterMgr.GetParameterByName((string)r["count"]).Expression=Convert.ToInt32(r["minimum"])==0?"0":"1";
 Check("jeden_uchwyt_zero_bocznych_zamkow");Picture(Path.Combine(folder,"po_jednym.png"));
 restore();S.ParameterMgr.GetParameterByName("RP_GlebokoscSkrzyni").Expression="972 mm";S.ParameterMgr.GetParameterByName("RP_WysokoscDolu").Expression="528.99 mm";S.ParameterMgr.GetParameterByName("RP_WysokoscCzapki").Expression="692.99 mm";
 foreach(var r in rows)S.ParameterMgr.GetParameterByName((string)r["count"]).Expression=((string)r["count"]).Contains("Lewa")?"3":"1";
 Check("trzy_i_jeden_z_gabarytami");Picture(Path.Combine(folder,"trzy_i_jeden.png"));
 restore();S.ParameterMgr.GetParameterByName("RP_GlebokoscSkrzyni").Expression="972 mm";foreach(var r in rows)S.ParameterMgr.GetParameterByName((string)r["count"]).Expression="4";
 Check("maksimum_cztery");restore();Check("powrot_do_dwoch");Picture(Path.Combine(folder,"final.png"));S.SaveAs(output,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);owned.Close2(true);owned=null;
 owned=app.OpenFile2(output,false,true,out already);if(already){owned=null;throw new Exception("Output already open");}ResetScene(owned);Check("ponowne_otwarcie");foreach(var r in rows)S.ParameterMgr.GetParameterByName((string)r["count"]).Expression="3";Check("liczba_po_otwarciu");restore();Check("finalny_powrot");Picture(Path.Combine(folder,"final.png"));S.SaveAs(output,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);
 foreach(var old in before){var d=((Array)app.GetAllOpenDocs()).Cast<object>().Select(D).Single(x=>x.Name==old.path);if(d.Modified!=old.modified)throw new Exception("Preexisting document changed "+old.path);}
 if(Hash(source)!=(string)q["sha256"])throw new Exception("Diagnostic source changed");
 Controller.GetMethod("Start").Invoke(null,new object[]{app});Controller.GetField("Suspended").SetValue(null,false);app.ActiveDoc=owned;
 result["source_unchanged"]=true;result["existing_documents_preserved"]=true;result["output"]=output;result["output_sha256"]=Hash(output);result["manifest"]=Manifest;
 result["parameters"]=Enumerable.Range(0,S.ParameterMgr.Count).Select(i=>S.ParameterMgr.GetParameter(i)).Select(p=>new{name=p.Name,expression=p.Expression,value=p.Value,type=p.Type.ToString(),notes=p.Notes}).ToArray();pass=true;
}catch(Exception e){result["error"]=e.ToString();if(owned!=null)try{S.SaveAs(Path.Combine(folder,"FAILED_DO_NOT_USE.ics"),eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);owned.Close2(true);}catch(Exception x){result["cleanup_error"]=x.ToString();}}
result["checks"]=Checks;result["passed"]=pass;File.WriteAllText(Path.Combine(folder,"result.json"),J.Serialize(result));return pass?0:1;}}}
